const { app, core } = require("photoshop");
const fs = require("uxp").storage.localFileSystem;
await core.executeAsModal(async () => {
  const folder = await fs.getFolder();
  const files = (await folder.getEntries()).filter(e => e.isFile && /\.psd$/i.test(e.name));
  for (const f of files) {
    const doc = await app.open(f);
    await doc.flatten();
    const out = await folder.createFile(f.name.replace(/\.psd$/i, ".jpg"), { overwrite: true });
    await doc.saveAs.jpg(out, { quality: 9 }, true);
    await doc.closeWithoutSaving();
  }
}, { commandName: "Batch JPEG" });

