const { app, core } = require("photoshop");
await core.executeAsModal(async (ctx) => {
  const doc = app.activeDocument;
  const h = await ctx.hostControl.suspendHistory({ documentID: doc.id, name: "Plugin cleanup" });
  try {
    for (const l of doc.layers) if (l.kind === "pixel" && l.bounds.width === 0) l.delete();
  } finally {
    await ctx.hostControl.resumeHistory(h);
  }
}, { commandName: "Cleanup" });

