const { app, core, constants } = require("photoshop");
await core.executeAsModal(async () => {
  const doc = app.activeDocument;
  const cols = 12, margin = 40, gutter = 24;
  const colW = (doc.width - 2 * margin - (cols - 1) * gutter) / cols;
  for (let i = 0; i < cols; i++) {
    const x = margin + i * (colW + gutter);
    doc.guides.add(constants.Direction.VERTICAL, x);
    doc.guides.add(constants.Direction.VERTICAL, x + colW);
  }
}, { commandName: "Column guides" });

